@Bean
public Plan plan() {
    return new Prepaid();
}

@Bean
public Customer customer() {
    Customer customer = new Customer();
    customer.setPlan(plan());  // Manual Wiring
    return customer;
}

@Component
public class Customer {

    @Autowired
    private Plan plan;

    // Getters and setters
}

@Component
public class Customer {

    private Plan plan;

    @Autowired
    public void setPlan(Plan plan) {
        this.plan = plan;
    }
}

@Component
public class Customer {

    private final Plan plan;

    @Autowired
    public Customer(Plan plan) {
        this.plan = plan;
    }
}

public interface Plan {
    void getPlanDetails();
}

@Component
public class Prepaid implements Plan {
    public void getPlanDetails() {
        System.out.println("Prepaid Plan Details");
    }
}

@Component
public class Postpaid implements Plan {
    public void getPlanDetails() {
        System.out.println("Postpaid Plan Details");
    }
}

@Component
public class Customer {

    private Plan plan;

    @Autowired
    @Qualifier("prepaid")  // Refers to the bean name
    public void setPlan(Plan plan) {
        this.plan = plan;
    }

    public void showPlan() {
        plan.getPlanDetails();
    }
}

@Configuration
@ComponentScan(basePackages = "com.infytel")
public class SpringConfig {}

public class App {
    public static void main(String[] args) {
        ApplicationContext context = new AnnotationConfigApplicationContext(SpringConfig.class);
        Customer customer = context.getBean(Customer.class);
        customer.showPlan();
    }
}

